"""Get variant ID from pyvcf in DataFrame"""
def df_variant_id(row: Any) -> object {
    if (row['ID'] != '.') {
        return row['ID'];
    } else {
        return (row['CHROM'] + ':' + str(row['POS']));
    }
}

